package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.View;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Read-only expired-card review based only on RouterOS usage/limit fields. */
public final class ExpiredCardsActivity extends Activity {private TextView status,out;private Spinner backend;private final ExecutorService worker=Executors.newSingleThreadExecutor();@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(16,18,16,28);p.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);p.setBackgroundColor(Color.rgb(237,244,250));ScrollView s=new ScrollView(this);s.addView(p);setContentView(s); UiTheme.apply(this);TextView t=new TextView(this);t.setText("الكروت المنتهية — مراجعة RouterOS");t.setTextSize(23);t.setTextColor(Color.rgb(22,47,80));p.addView(t);backend=new Spinner(this);backend.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Hotspot","User Manager v6","User Manager v7"}));p.addView(backend);status=txt("جاري الفحص",14);p.addView(status);out=txt("",14);p.addView(out);Button bRefresh=new Button(this);bRefresh.setText("إعادة الفحص");bRefresh.setOnClickListener(v->load());p.addView(bRefresh);load();}private void load(){worker.execute(()->{try{String be=backend.getSelectedItem().toString(),ver=be.contains("v6")?"6.":"7.";android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=new SecureConnectionStore(this).get();try(RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false))){r.login(p.getString("user",""),pw==null?"":pw);List<Map<String,String>> rows=be.startsWith("Hotspot")?new HotspotService(r).users():new UserManagerService(r).users(ver);StringBuilder b=new StringBuilder();int n=0;for(Map<String,String> x:rows){String used=x.getOrDefault("uptime-used","");String limit=x.getOrDefault("limit-uptime","");if(!used.isEmpty()&&!limit.isEmpty()&&used.equals(limit)){b.append(x.getOrDefault("name",x.getOrDefault("username",""))).append(" | ").append(x.getOrDefault("profile","")).append(" | ").append(used).append("\n");n++;}}final int total=n;ui(()->{status.setText("انتهى حسب تطابق uptime-used و limit-uptime: "+total);out.setText(total==0?"لا توجد حالات مؤكدة من الحقول المتاحة":b.toString());});}}catch(Exception e){ui(()->status.setText("تعذر الفحص: "+(e.getMessage()==null?"خطأ":e.getMessage())));}});}private TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(22,47,80));t.setPadding(8,10,8,10);return t;}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}}
